            while (rs.next()) {
                String type = rs.getString("TABLE_TYPE");
                String name = rs.getString("TABLE_NAME");
                if (type != null && type.contains("TABLE") && !NOT_SHEET_DATA.contains(name)) columns.put(name, new ArrayList<>());
