            try (ResultSet rs = meta.getColumns(null, schema, e.getKey(), "%")) {
                Map<Integer, String> ordered = new TreeMap<>();
                while (rs.next()) ordered.put(rs.getInt("ORDINAL_POSITION"), rs.getString("COLUMN_NAME"));
